import { test, expect } from '@playwright/test';

test('add MCP server and verify persistence', async ({ page }) => {
  await page.goto('http://localhost:8181/settings');

  await page.getByRole('button', { name: 'Add MCP server' }).click();

  await page.getByLabel('Name').fill('Local tools');
  await page.getByLabel('URL').fill('http://127.0.0.1:9000/mcp');

  await page.getByRole('button', { name: 'Save' }).click();

  await expect(page.getByText('Local tools')).toBeVisible();

  await page.reload();

  await expect(page.getByText('Local tools')).toBeVisible();
});
